create table if not exists public.domingos_properties(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,location text not null,type text not null,status text not null default 'Venda',price numeric,bedrooms integer,bathrooms integer,area_m2 numeric,image_url text not null,description text,featured boolean not null default false,published boolean not null default true,created_at timestamptz not null default now());create table if not exists public.domingos_leads(id uuid primary key default gen_random_uuid(),name text not null,email text not null,phone text,subject text,message text not null,created_at timestamptz not null default now());alter table public.domingos_properties enable row level security;alter table public.domingos_leads enable row level security;drop policy if exists "Public can read published properties" on public.domingos_properties;create policy "Public can read published properties" on public.domingos_properties for select to anon,authenticated using(published=true);revoke all on public.domingos_leads from anon,authenticated;grant select on public.domingos_properties to anon,authenticated;grant all on public.domingos_properties to service_role;grant all on public.domingos_leads to service_role;insert into public.domingos_properties(slug,title,location,type,status,price,bedrooms,bathrooms,area_m2,image_url,description,featured) values('moradia-contemporanea-sintra','Moradia contemporânea com piscina','Sintra','Moradia','Venda',895000,4,3,395,'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1400&q=85','Moradia contemporânea com espaços amplos, luz natural e piscina.',true),('apartamento-contemporaneo-lisboa','Apartamento contemporâneo','Lisboa','Apartamento','Venda',520000,2,2,118,'https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=1200&q=85','Apartamento moderno numa localização central de Lisboa.',false) on conflict(slug) do nothing;